"""Create self-contained local pages from reviewed calculation sources.

Uses Python standard library only. KaTeX is browser-only, with embedded fonts.
"""
from __future__ import annotations
import json
from pathlib import Path
from .release import PREFIX

ROOT=Path(__file__).resolve().parents[1]


def assets():
    css=(ROOT/'web/20261018_v1_KaTeXInline.css').read_text(encoding='utf-8')
    js=(ROOT/'web/20261018_v1_KaTeX.min.js').read_text(encoding='utf-8')
    return css,js


def build_tool():
    css,katex=assets()
    case=(ROOT/(PREFIX+'CaseStudyInputs.json')).read_text(encoding='utf-8')
    fixtures=(ROOT/(PREFIX+'ParityVectors.json')).read_text(encoding='utf-8')
    scripts='\n'.join((ROOT/'web'/n).read_text(encoding='utf-8') for n in ['connections.js','materials_fire_racking.js','seismic.js','toolkit.js'])
    flags=''.join(f'<label>{label}<select id="rack-{key}"><option value="unknown">Unverified</option><option value="true">Confirmed for this subcheck</option><option value="false">Not satisfied</option></select></label>' for key,label in [('tied_down','End tie-downs'),('no_openings','No openings in the assessed panel'),('regular_spacing','Constant perimeter spacing'),('sheet_edge_sufficient','Sheet edge detailing'),('sheet_fixings_verified','Fastener and sheet fixing checks')])
    html=r'''<!doctype html><html lang="en-GB"><head><link rel="icon" href="data:,"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Timber façade connection toolkit</title>
<style>__KATEX_CSS__
:root{--bg:#f6f7fb;--ink:#0f172a;--muted:#475569;--accent:#2563eb;--line:#dce2ec}*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 Arial,sans-serif}header{padding:22px 28px;background:linear-gradient(180deg,#fff,#f6f7fb);border-bottom:1px solid var(--line)}h1{font-size:27px;line-height:1.15;margin:3px 0 10px}h2{font-size:18px;margin:0 0 12px}h3{font-size:16px;margin:12px 0}p{margin:8px 0 12px}a{color:#1d4ed8}button,input,select,textarea{font:inherit}button{padding:9px 13px;border:1px solid #aebdce;border-radius:8px;background:white;cursor:pointer}button.primary{background:var(--accent);color:white;border-color:var(--accent)}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible,a:focus-visible{outline:3px solid #2563eb;outline-offset:3px}main{display:grid;grid-template-columns:365px minmax(0,1fr);gap:20px;max-width:1500px;padding:20px;margin:auto}aside,.card{background:white;border:1px solid var(--line);border-radius:12px;padding:18px}aside{align-self:start}.card{margin-bottom:18px}.muted,small{color:var(--muted)}small{display:block}.notice{color:#805008;font-weight:bold}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:12px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding-top:12px}label{font-size:13px;display:block;color:#334155}input,select{width:100%;border:1px solid #aebdce;border-radius:5px;padding:7px;margin:4px 0 8px}input::placeholder{font-size:12px}details{border-top:1px solid var(--line);padding:13px 0}summary{cursor:pointer;font-weight:bold;font-size:15px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:18px}.metric{background:white;border:1px solid var(--line);border-radius:10px;padding:16px}.metric strong{font-size:28px;color:#1d4ed8;display:block}.metric span{font-size:12px;color:#475569}.two{display:grid;grid-template-columns:1fr 1fr;gap:18px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:8px;border-bottom:1px solid var(--line);vertical-align:top}th{background:#f1f5f9}svg{width:100%;height:auto}svg text{font:12px Arial,sans-serif;fill:#475569}textarea{width:100%;min-height:220px;font:12px/1.45 Consolas,monospace;resize:vertical;border:1px solid #aebdce;padding:10px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.45 Consolas,monospace;background:#f8fafc;padding:12px;max-height:450px;overflow:auto}.error{padding:20px;color:#991b1b;background:#fff1f2;border:1px solid #fecdd3;border-radius:10px}footer{padding:25px;max-width:1400px;margin:auto;color:#475569;font-size:13px}.katex-display{overflow:auto;font-size:.95em}.tag{font-size:12px;color:#475569;letter-spacing:.04em;text-transform:uppercase}ul{padding-left:20px}@media(max-width:1050px){main{grid-template-columns:1fr}aside .fields{grid-template-columns:repeat(3,1fr)}}@media(max-width:680px){header{padding:18px}main{padding:12px}.two,.metrics{grid-template-columns:1fr}.fields,aside .fields{grid-template-columns:1fr 1fr}h1{font-size:23px}}@media print{aside,.actions,#equation-runner{display:none}main{display:block}.card{break-inside:avoid}body{background:white}}</style></head>
<body><style>main>*{min-width:0}.fields>*{min-width:0}input,select,textarea,button{max-width:100%}@media(max-width:1050px){main{grid-template-columns:minmax(0,1fr)}aside .fields{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:680px){.fields,aside .fields{grid-template-columns:minmax(0,1fr)}.two,.metrics{grid-template-columns:minmax(0,1fr)}header,.card,aside,footer{overflow-wrap:anywhere}.metric strong{font-size:25px}}</style><header><div class="tag">Independent study | 18 October 2026 | AI-assisted development</div><h1>Timber façade connection toolkit</h1><p>Explore connection resistance, seismic demand, unprotected-member section loss and a conditional racking subcheck.</p><p class="notice">Educational tool, not for design. Inputs are illustrative. No overall façade design pass is reported.</p><p><a href="20261018_v1_TechnicalNote.html">Technical note and verification</a> · <a href="20261018_v1_LearningGuide.md">Learning guide</a> · <a href="README.md">Scope and provenance</a></p></header>
<main><aside><h2>Case-study inputs</h2><p class="muted">Blank fields remain required. Changing a number does not verify the real product, load path or National Annex.</p><div class="actions"><button id="reset">Restore illustrative case</button><button id="download">Download current inputs</button></div><div id="fields"></div><label>Anchor ETA source reference, required<input id="eta-reference" placeholder="Required manufacturer ETA reference"></label>
<details><summary>Seismic classification and movement</summary><label>Damage-limitation classification<select id="category"><option value="brittle">Brittle attached element</option><option value="ductile">Ductile element</option><option value="non_interfering">Fixed so as not to interfere</option></select></label><label>Justified bracket load shares, comma-separated<input id="shares" placeholder="Required; shares must sum to 1"></label><p class="muted">Shares must follow a justified load-path model. A sliding bracket alone does not establish the non-interfering classification.</p></details>
<details><summary>Fire orientation</summary><label>Explicit exposed face<select id="face"><option value="depth_front">One face reducing the section depth</option><option value="width_left">One face reducing the section width</option><option value="width_left,width_right,depth_front">Three faces</option></select></label><p class="muted">The isolated-member study does not assess the insulated assembly or protected members.</p></details>
<details><summary>Racking applicability</summary>__FLAGS__<p class="muted">Confirm only documented conditions. Remaining whole-wall checks are outside this subcheck.</p></details>
<details><summary>Complete case JSON</summary><p class="muted">All case values and assumptions are in one editable record. In-page changes remain local until downloaded.</p><textarea id="json" aria-label="Complete case-study JSON" spellcheck="false"></textarea><button id="apply-json">Apply JSON locally</button></details></aside>
<section aria-label="Calculation results"><div id="error" class="error" role="alert" hidden></div><div id="results">
<div class="metrics"><div class="metric"><small>Connection component</small><strong id="connection-metric"></strong><span id="connection-caption"></span></div><div class="metric"><small>Whole-panel seismic force</small><strong id="seismic-metric"></strong><span>Demand only; bracket shares and anchors remain separate</span></div><div class="metric"><small>Last fire-time effective section</small><strong id="fire-metric"></strong><span>Isolated member, explicit exposure orientation</span></div></div>
<section class="card"><h2>Dowel-type connection</h2><div id="connection-notes"></div><div id="modes"></div><p id="source-clause" class="muted"></p><p>Values are per fastener and per shear plane. This case uses single shear. The equation runner includes all implemented timber-to-timber and steel-to-timber configurations.</p><details><summary>Spacing, end and edge checks</summary><div id="spacings"></div></details><h3>Information still required</h3><ul id="required"></ul><p class="muted">Steel/fastener resistance, timber splitting, net section, bracket bending/prying, combined actions, actual three-dimensional load paths and full concrete anchorage are not established.</p><div id="boltplot"></div><small>Diameter sweep holds plate thickness, timber penetration and other case inputs fixed. It displays a resistance expression, with detailing and plate-fit conditions still applicable.</small></section>
<div class="two"><section class="card"><h2>Seismic force and drift</h2><div data-tex="F_a=\frac{S_a W_a\gamma_a}{q_a}"></div><div id="seismic-output"></div><div id="seismicplot"></div><small>EN 1998-1:2004 4.3.5.2, Equations 4.24 and 4.25; damage limitation 4.4.3.2. The slot is a declared geometric illustration for full reversing drift, not a code-approved connection detail.</small></section>
<section class="card"><h2>Unprotected-member fire study</h2><div data-tex="d_{\mathrm{ef}}=\beta_n t+k_0 d_0"></div><div id="fire-output"></div><p id="fire-status" class="notice"></p><div id="fireplot"></div><small>Blue: effective depth after notional char and zero-strength layer. Dashed grey: physical notional-char residual depth. EN 1995-1-2:2004 3.4.2 and 4.2.2. No assembly fire rating is inferred.</small></section></div>
<section class="card"><h2>Method A racking subcheck</h2><div data-tex="F_{i,v,Rd}=\frac{F_{f,Rd}b_i c_i}{s},\qquad c_i=\min\left(1,\frac{2b_i}{h}\right)"></div><div id="racking-output"></div><p id="rack-required" class="notice"></p><p class="muted">EN 1995-1-1 9.2.4.2. A Section 8 fastener resistance receives the 1.2 sheet-edge enhancement once. If the supplied value is already enhanced, set that explicit flag in the case JSON. Tie-downs, sheet details and all other prerequisites must be established.</p></section>
</div><section class="card" id="equation-runner"><h2>Explore individual verified equations</h2><p>These are separately labelled verification fixtures, not changes to the façade case. Choose a function family, inspect its inputs, change them deliberately and compare the result with the source.</p><label>Calculation fixture<select id="fixture"></select></label><textarea id="fixture-inputs" aria-label="Equation fixture inputs" spellcheck="false"></textarea><button id="run-fixture" class="primary">Run equation</button><pre id="fixture-output" aria-live="polite"></pre></section>
<section class="card"><h2>Sources and limits</h2><p>Equations use the cited 2004 standards framework, with explicitly identified A1/A2 provisions where used. Material tables reflect the cited 2022 handbook's EN 338 and EN 14080 references. Current project standards and National Annex choices are not verified by this page.</p><ul><li><a href="https://www.universityofgalway.ie/media/timberengineeringresearchgroup/Design-of-timber-structures_Volume2_Rules-and-formulas-according-to-Eurocode-5.pdf">Design of timber structures Volume 2, UK edition 1:2022</a></li><li><a href="https://www.svenskttra.se/siteassets/5-publikationer/pdfer/sw-design-of-timber-structures-vol3-2022.pdf">Volume 3, edition 3:2022, worked Examples 4.1 and 4.2</a></li><li><a href="https://www.phd.eng.br/wp-content/uploads/2015/12/en.1995.1.1.2004.pdf">Public EN 1995-1-1:2004+A1:2008 source copy</a></li><li><a href="https://www.phd.eng.br/wp-content/uploads/2015/12/en.1995.1.2.2004.pdf">Public EN 1995-1-2:2004 source copy</a></li><li><a href="https://www.phd.eng.br/wp-content/uploads/2015/02/en.1998.1.2004.pdf">Public EN 1998-1:2004 source copy</a></li></ul><p>The code and documentation were developed with AI assistance. Verification compares the implementations with hand calculations, published worked examples and each other. No laboratory testing, physical validation or product approval is represented. The complete input JSON includes an optional learner verification record, separate from the development checks.</p></section></section></main>
<footer>Independent educational study. No project, company or consortium affiliation is implied. Calculations run in the browser without telemetry. Source links open when selected. Mathematical typography uses <a href="web/20261018_v1_KaTeX_LICENSE.txt">KaTeX, MIT licence</a>.</footer>
<script id="case-data" type="application/json">__CASE__</script><script id="fixture-data" type="application/json">__FIXTURES__</script><script>__KATEX_JS__</script><script>__SCRIPTS__</script></body></html>'''
    for key,value in {'__KATEX_CSS__':css,'__KATEX_JS__':katex,'__CASE__':case,'__FIXTURES__':fixtures,'__SCRIPTS__':scripts,'__FLAGS__':flags}.items():html=html.replace(key,value)
    html=html.replace('20261018_v1_TechnicalNote.html', PREFIX+'TechnicalNote.html').replace('20261018_v1_LearningGuide.md', PREFIX+'LearningGuide.md')
    html=html.replace('20261018_v1_EditedCaseInputs.json', PREFIX+'EditedCaseInputs.json')
    html=html.replace('<a href="README.md">Scope and provenance</a>', '<a href="README.md">Scope and provenance</a> · <a href="'+PREFIX+'TestAndAssemblyPlan.html">Proposed test and assembly plan</a>')
    notice=(ROOT/'web/20261018_v1_KaTeX_LICENSE.txt').read_text(encoding='utf-8')
    html=html.replace('</html>', '<!-- KaTeX third-party licence\n'+notice+'\n--></html>')
    assert '\u2014' not in html
    # The portfolio builder owns index.html; never overwrite it here.
    (ROOT/(PREFIX+'Toolkit.html')).write_text(html,encoding='utf-8',newline='\r\n')
    return len(html)


def main():
    print(json.dumps({'self_contained_tool_bytes':build_tool()},indent=2))


if __name__=='__main__':main()
